"""Bundled Glasshouse client. Kept buildless so `replicanta --web` stays local."""

APP_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Replicanta Glasshouse</title><link rel="stylesheet" href="/app.css"></head><body><header><b><i>R</i> REPLICANTA <em>glasshouse</em></b><nav><button data-view="habitat" class="on">Habitat</button><button data-view="atlas">Mind atlas</button><button data-view="memory">Timeline</button><button data-view="inner">Inner</button><button data-view="cells">Cells</button></nav><span id="local">● local</span><button id="still">Stillness</button></header><aside id="nursery"><small>NURSERY</small><div id="orgs"></div><form id="grow" class="grow"><input id="grow-name" aria-label="Name the new organism" placeholder="Name the new organism…" autocomplete="off"><button id="new">Grow</button></form></aside><main><section id="heading"><small>HABITAT · <span data-name></span></small><h1>A mind in cultivation.</h1><p>Everything it senses, remembers, and changes remains visible to you.</p></section><section id="habitat" class="view on"><div class="specimen card"><small>LIVE SPECIMEN <span id="state"></span></small><div class="field"><div class="rings"></div><div class="orb"><span data-name></span></div></div><div class="meters"><label>Mood <b id="mood"></b></label><label>Stress <b id="stress"></b></label><label>Grounding <b id="ground"></b></label><label>Chaos <input id="chaos" type="range" min="0" max="1" step=".05"></label></div></div><div class="chat card"><h2>Conversation</h2><div id="help-panel" class="help-panel" hidden><div class="help-head"><h3>Slash commands</h3><button id="help-close" type="button" aria-label="Close help">×</button></div><dl id="help-list"></dl></div><div id="messages"></div><div class="voice-bar"><label class="speak" title="Read organism replies aloud"><input id="speak" type="checkbox">Speak replies</label><button id="listen" type="button" aria-label="Hold to speak" title="Hold to speak">Listen</button></div><form id="chat"><textarea aria-label="Message" placeholder="Teach, ask, or wonder aloud…"></textarea><button>↑</button></form><div id="slash-helper" class="slash-helper" hidden></div></div></section><section id="atlas" class="view"><div id="beliefs" class="card list"></div></section><section id="memory" class="view"><div id="episodes" class="card list"></div></section><section id="inner" class="view"><div class="card inner"><small>INNER STATE</small><div id="scalars"></div></div></section><section id="cells" class="view"><div class="card cells"><small>CELL FIELD</small><div id="cell-grid" role="grid" aria-label="Beliefs, goals and skills"></div></div></section></main><aside id="steward"><h2>Tendril</h2><p>What you tend here shapes what it becomes.</p><label>Auto-apply mutations <input id="auto" type="checkbox"></label><label>Speak replies <input id="speak-aside" type="checkbox" title="Read organism replies aloud"></label><label>Attention <input id="focus" placeholder="Guide attention"></label><div id="mutation"></div><button id="sleep">Sleep / wake</button><p class="warning">This is a sandbox, not a being. Speak to it as a garden.</p></aside><dialog id="trace"><button id="close">×</button><small>OPEN LENS</small><h2>Cognitive trace</h2><p>This is a process summary, not hidden reasoning or proof of consciousness.</p><ol><li>Perceived your message</li><li>Extracted learnable facts</li><li>Recalled relevant beliefs and skills</li><li>Considered candidate responses</li><li>Recorded resulting changes</li></ol></dialog><script src="/app.js"></script></body></html>'''

APP_CSS = r''':root{--p:#f3f0e7;--i:#17251e;--g:#174235;--m:#687068;--l:#dfe6d8}*{box-sizing:border-box}body{margin:0;background:var(--p);color:var(--i);font:14px Arial;display:grid;grid-template:64px 1fr/190px 1fr 250px;min-height:100vh}header{grid-column:1/-1;display:flex;align-items:center;gap:30px;padding:0 20px;border-bottom:1px solid #0002}header b{letter-spacing:2px}header b i{display:inline-grid;place-items:center;background:var(--g);color:white;border-radius:50%;width:28px;height:28px;font:16px Georgia}header em{font:12px Georgia;color:var(--m);letter-spacing:0}nav{display:flex;height:100%}button{cursor:pointer}nav button{border:0;background:none;padding:0 16px;color:var(--m)}nav button.on{border-bottom:2px solid var(--g);color:var(--g)}#local{margin-left:auto;color:#478052;font-size:11px}#still{border:1px solid var(--g);background:none;padding:8px 12px;color:var(--g)}aside{padding:28px 15px;border-right:1px solid #0002}aside#steward{border-right:0;border-left:1px solid #0002}aside small,main>section>small{letter-spacing:2px;font-size:9px;color:var(--m)}#orgs button,#new{width:100%;text-align:left;border:0;background:none;padding:12px;margin-top:8px}.grow{display:grid;grid-template-columns:1fr auto;gap:6px;margin-top:8px;align-items:center}#grow-name{width:100%;border:1px solid #0002;background:#fff7;padding:8px;font:13px Arial;color:var(--i)}.grow button{border:1px solid var(--g);padding:8px 12px;color:var(--g);background:none;width:auto;white-space:nowrap}#orgs button.on{background:#dfe1d7}#orgs b{font:15px Georgia}#orgs span{display:block;font-size:9px;color:var(--m)}main{padding:35px;min-width:0}h1{font:34px Georgia;margin:8px 0}#heading p{font:italic 14px Georgia;color:var(--m)}.view{display:none}.view.on{display:grid}.view#habitat{grid-template-columns:.8fr 1.2fr;gap:14px}.card{border:1px solid #0002;background:#fff7}.specimen>small{display:flex;justify-content:space-between;padding:14px}.field{height:330px;display:grid;place-items:center;background:linear-gradient(#1742350b 1px,transparent 1px),linear-gradient(90deg,#1742350b 1px,transparent 1px);background-size:24px 24px;overflow:hidden}.orb{width:145px;height:145px;border-radius:45% 55%;background:radial-gradient(circle at 35% 30%,#e2ed9d,#75a16b 30%,#174235 75%);box-shadow:0 0 45px #527c5a66;display:grid;place-items:center;color:#eef5d2;animation:breathe 5s infinite}.rings{position:absolute;width:220px;height:180px;border:1px solid #17423533;border-radius:50%;animation:spin 15s linear infinite}.meters{display:grid;grid-template-columns:1fr 1fr}.meters label{padding:14px;border-top:1px solid #0002;font-size:10px}.meters b{float:right;font:12px Georgia}.chat{display:flex;flex-direction:column;height:490px}.chat h2{font:14px Georgia;padding:14px;margin:0;border-bottom:1px solid #0002}#messages{padding:16px;overflow:auto;flex:1}.msg{max-width:85%;background:#e3e0d6;padding:12px;margin:10px 0;font:14px/1.5 Georgia}.msg.org{background:var(--l);border-left:2px solid var(--g)}.msg button{display:block;border:0;border-top:1px solid #0002;background:none;color:var(--g);font-size:9px;margin-top:8px;padding-top:8px}form{display:grid;grid-template-columns:1fr 35px;border-top:1px solid #0002;padding:10px}textarea{border:0;background:none;resize:none;outline:0;padding:8px}form button{border:0;border-radius:50%;background:var(--g);color:white;width:32px;height:32px}.list article{padding:16px;border-bottom:1px solid #0002;display:grid;grid-template-columns:1fr auto}.list h3{font:16px Georgia;margin:0}.list p{color:var(--m);font-size:11px}.list b{font:14px Georgia}#steward h2{font:20px Georgia;margin:0}#steward>p{color:var(--m);font-size:10px}#steward label{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #0002;padding:14px 0;font:12px Georgia}#focus{width:100px}.mutation{background:#eee4c9;padding:12px;margin:15px 0}.mutation b{font:14px Georgia}.mutation button{margin:8px 4px 0 0}.warning{margin-top:30px!important;line-height:1.5}dialog{border:0;width:min(480px,90vw);padding:30px;box-shadow:0 20px 80px #0005}dialog::backdrop{background:#15271fcc}dialog #close{float:right;border:0;background:none;font-size:24px}dialog h2{font:28px Georgia}dialog li{padding:10px;border-top:1px solid #0002}body.still .orb,body.still .rings{animation-play-state:paused;filter:grayscale(1)}@keyframes breathe{50%{transform:scale(1.05) rotate(2deg)}}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:900px){body{display:block}header{height:60px;position:sticky;top:0;background:var(--p);z-index:2}header nav{display:none}aside{display:none}main{padding:20px}.view#habitat{grid-template-columns:1fr}.chat{height:520px}}
.view#inner,.view#cells{grid-template-columns:1fr;gap:14px}
.inner,.cells{display:flex;flex-direction:column;min-height:490px}
.inner>small,.cells>small{display:block;padding:14px;border-bottom:1px solid #0002}
#scalars{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:14px;padding:16px}
.scalar{border:1px solid #0002;background:var(--p);padding:14px;display:grid;gap:6px}
.scalar small{color:var(--m);font-size:9px;letter-spacing:2px}
.scalar b{font:20px Georgia;text-align:right}
.scalar .bar{height:6px;background:#0001;border-radius:3px;overflow:hidden}
.scalar .bar i{display:block;height:100%;background:var(--g);width:0%}
#cell-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(110px,1fr));gap:10px;padding:16px;flex:1;overflow:auto}
.cell{aspect-ratio:1/1;border:1px solid #0002;background:var(--l);display:flex;flex-direction:column;justify-content:center;align-items:center;padding:10px;text-align:center;cursor:pointer;transition:transform .15s,border-color .15s}
.cell:hover,.cell:focus{transform:translateY(-3px);border-color:var(--g);outline:0}
.cell .type{font-size:9px;letter-spacing:2px;color:var(--m);text-transform:uppercase}
.cell .name{font:13px Georgia;margin-top:4px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.cell.belief{background:#e3e0d6}
.cell.goal{background:#eee4c9}
.cell.skill{background:#dfe6d8}
#cell-tip{min-height:1.5em;color:var(--m);font-size:11px;padding:0 16px 16px}
.voice-bar{display:flex;justify-content:space-between;align-items:center;padding:10px 16px;border-bottom:1px solid #0002;gap:10px}
.voice-bar label.speak{display:flex;align-items:center;gap:8px;font:12px Georgia;cursor:pointer}
.voice-bar input[type=checkbox]{margin:0}
#listen{border:1px solid var(--g);background:var(--g);color:white;padding:8px 14px;font:12px Georgia;border-radius:4px;transition:background .15s,transform .1s}
#listen:disabled{opacity:.5;cursor:not-allowed;background:var(--m);border-color:var(--m)}
#listen.active{background:#5a7d62;transform:scale(.98)}
#speak-aside input[type=checkbox]{margin-left:8px}
.help-panel{background:#fff7;border-bottom:1px solid #0002;padding:14px;max-height:260px;overflow:auto}
.help-panel[hidden]{display:none}
.help-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}
.help-panel h3{margin:0;font:14px Georgia;color:var(--i)}
.help-panel dl{margin:0}
.help-panel dt{font:12px Georgia;color:var(--g);margin-top:8px}
.help-panel dd{margin:0 0 4px 0;font-size:11px;color:var(--m)}
#help-close{border:0;background:none;font-size:22px;color:var(--m);cursor:pointer}
.slash-helper{position:absolute;bottom:100%;left:10px;right:10px;background:#fff7;border:1px solid #0002;max-height:180px;overflow:auto;z-index:3}
.slash-helper[hidden]{display:none}
.slash-item{padding:8px 12px;cursor:pointer;border-bottom:1px solid #0001;font-size:12px}
.slash-item:hover,.slash-item.on{background:var(--l)}
.slash-item b{font:13px Georgia;color:var(--g)}
.slash-item span{color:var(--m);font-size:10px;margin-left:8px}
.msg.cmd{background:#f0ebe1;border-left:2px solid var(--m);font-style:italic;color:var(--m)}
.msg.cmd small{color:var(--m);font-weight:700}
#chat{position:relative}
@media(max-width:900px){.view#inner,.view#cells{min-height:auto}#scalars{grid-template-columns:1fr 1fr}}
'''

APP_JS = r'''const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let state;let speakEnabled=false;let slashList=[];let slashIndex=-1;let commandLog=[];const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;let recognition=null;let listening=false;
if(SpeechRecognition){recognition=new SpeechRecognition();recognition.continuous=false;recognition.interimResults=true;recognition.lang='en-US';recognition.onresult=e=>{const t=e.results[e.resultIndex];const txt=t[0].transcript;if(t.isFinal&&txt.trim()){submitChat(txt.trim())}};recognition.onerror=e=>{console.warn('speech error',e.error);stopListen()};recognition.onend=stopListen}
const COMMANDS=[{name:'/help',args:'',desc:'toggle this help panel',endpoint:'help'},{name:'/mutate',args:' [text]',desc:'propose a mutation seed',endpoint:'mutate'},{name:'/cycle',args:'',desc:'advance one full wake-sleep cycle',endpoint:'cycle'},{name:'/rename',args:' <name>',desc:'rename the current organism',endpoint:'rename'},{name:'/remember',args:' <text>',desc:'remember this text as an episode',endpoint:'remember'},{name:'/forget',args:' <text>',desc:'forget entries containing text',endpoint:'forget'},{name:'/goal',args:' <text>',desc:'set a new goal',endpoint:'goal'},{name:'/priority',args:' <goal>',desc:'move matching goal to front',endpoint:'priority'},{name:'/attention',args:' <topic>',desc:'focus attention on a topic',endpoint:'attention'},{name:'/mode',args:' <wake|sleep|revive>',desc:'set lifecycle mode',endpoint:'mode'},{name:'/save',args:'',desc:'persist organism state now',endpoint:'save'},{name:'/load',args:'',desc:'reload organism from disk',endpoint:'load'},{name:'/reset',args:'',desc:'reset the current organism',endpoint:'reset'},{name:'/chat',args:' <message>',desc:'send a normal chat message',endpoint:'chat'}];
function submitChat(text){const t=$('#chat textarea');t.value=text;t.dispatchEvent(new Event('input',{bubbles:true}));$('#chat').requestSubmit()}
function startListen(){if(!recognition||listening)return;listening=true;$('#listen').classList.add('active');$('#listen').textContent='Listening…';try{recognition.start()}catch(e){stopListen()}}
function stopListen(){listening=false;const b=$('#listen');if(b){b.classList.remove('active');b.textContent='Listen'}if(recognition){try{recognition.stop()}catch(e){}}}
function speak(text){if(!speakEnabled||!window.speechSynthesis)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=1;u.pitch=1;window.speechSynthesis.speak(u)}
function showSlash(){const h=$('#slash-helper');if(!slashList.length){h.hidden=true;return}h.innerHTML=slashList.map((c,i)=>`<div class="slash-item ${i===slashIndex?'on':''}" data-full="${esc(c.name)}"><b>${esc(c.name)}</b><span>${esc(c.args?c.args.slice(1):'')} — ${esc(c.desc)}</span></div>`).join('');h.hidden=false}
function handleSlash(){const t=$('#chat textarea');const v=t.value;if(!v.startsWith('/')){slashList=[];slashIndex=-1;showSlash();return}const needle=v.slice(1).split(' ')[0].toLowerCase();slashList=COMMANDS.filter(c=>c.name.slice(1).startsWith(needle));slashIndex=slashList.length?0:-1;showSlash()}
function renderHelp(){const dl=$('#help-list');if(!dl)return;dl.innerHTML=COMMANDS.map(c=>`<dt>${esc(c.name)}${esc(c.args)}</dt><dd>${esc(c.desc)}</dd>`).join('')}
async function handleCommand(text){const parts=text.split(' ');const name=parts[0].toLowerCase();const rest=text.slice(name.length).trim();commandLog.push({role:'cmd',text:text});if(commandLog.length>50)commandLog.shift();if(name==='/help'){$('#help-panel').hidden=!$('#help-panel').hidden;renderHelp();return {state:state}}if(name==='/chat'){if(!rest)throw new Error('chat needs a message');return api('chat',{text:rest})}const ep=COMMANDS.find(c=>c.name===name);if(!ep)throw new Error('unknown command '+name);let data={};if(ep.endpoint==='rename')data={name:rest};else if(['remember','forget','goal','mutate'].includes(ep.endpoint))data={text:rest};else if(ep.endpoint==='priority')data={goal:rest};else if(ep.endpoint==='attention')data={topic:rest};else if(ep.endpoint==='mode')data={mode:rest};return api(ep.endpoint,data)}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):null});const j=await r.json();if(!r.ok)throw Error(j.error);return j}
function render(s){const prevChat=state?state.chat.length:0;state=s;$$('[data-name]').forEach(x=>x.textContent=s.organism.name);$('#state').textContent=s.organism.state.toUpperCase();$('#mood').textContent=s.organism.mood;$('#stress').textContent=s.organism.stress;$('#ground').textContent=s.organism.rationality;$('#chaos').value=s.organism.chaos;$('#auto').checked=s.organism.auto_apply;const msgs=s.chat.map(m=>`<div class="msg ${m.role==='org'?'org':''}"><small>${m.role==='org'?s.organism.name:'YOU'}</small><div>${esc(m.text)}</div>${m.role==='org'?'<button class="why">⌁ How did this form?</button>':''}</div>`).concat(commandLog.map(m=>`<div class="msg cmd"><small>COMMAND</small><div>${esc(m.text)}</div></div>`));$('#messages').innerHTML=msgs.join('');$('#messages').scrollTop=1e9;if(s.chat.length>prevChat){const last=s.chat[s.chat.length-1];if(last.role==='org'){speak(last.text)}};const lb=$('#listen');if(lb){lb.disabled=!SpeechRecognition;lb.textContent=listening?'Listening…':'Listen'};renderInner(s);renderCells(s);$('#beliefs').innerHTML='<h2>What this mind holds to be true</h2>'+s.beliefs.map(b=>`<article><div><h3>${esc(b.subject)} <em>${esc(b.relation)}</em> ${esc(b.value)}</h3><p>Inspectable symbolic belief</p></div><b>${Math.round(b.confidence*100)}%</b></article>`).join('');$('#episodes').innerHTML='<h2>Developmental timeline</h2>'+s.memory.map(e=>`<article><div><h3>${esc(e.kind)}</h3><p>${esc(e.text)}</p></div><b>cycle ${e.cycle}</b></article>`).join('');$('#orgs').innerHTML=s.nursery.organisms.map(n=>`<button data-org="${esc(n)}" class="${n===s.organism.name?'on':''}"><b>${esc(n)}</b><span>${n===s.organism.name?s.organism.state:'stored'}</span></button>`).join('');const p=s.extensions.pending;$('#mutation').innerHTML=p?`<div class="mutation"><small>PENDING MUTATION</small><p><b>${esc(p.kind)}</b></p><button data-mut="approve">Approve</button><button data-mut="reject">Reject</button></div>`:'';bindDynamic()}
function renderInner(s){const o=s.organism,m=s.metrics||{};const scalars=[{k:'Cycle',v:o.cycle||0,bar:false},{k:'Stress',v:o.stress??0,bar:true},{k:'Arousal',v:o.arousal??0,bar:true},{k:'Rationality',v:o.rationality??0,bar:true},{k:'Irrationality',v:o.irrationality??0,bar:true},{k:'Chaos',v:o.chaos??0,bar:true},{k:'Beliefs',v:m.beliefs??0,bar:false},{k:'Rules',v:m.rules??0,bar:false}];$('#scalars').innerHTML=scalars.map(x=>{const pct=Math.min(100,Math.max(0,Number(x.v)*100));const bar=x.bar?`<div class="bar" aria-hidden="true"><i style="width:${pct}%"></i></div>`:'';return `<div class="scalar"><small>${esc(x.k)}</small><b>${esc(x.v)}</b>${bar}</div>`}).join('')}function renderCells(s){const items=[...s.beliefs.map(b=>({type:'belief',name:`${b.subject} ${b.relation} ${b.value}`,detail:`confidence ${Math.round(b.confidence*100)}%`})),...s.goals.map(g=>({type:'goal',name:g,detail:'goal'})),...s.skills.map(sk=>({type:'skill',name:sk.name,detail:`used ${sk.uses||0} times`}))];$('#cell-grid').innerHTML=items.map((it,i)=>`<div class="cell ${esc(it.type)}" role="gridcell" tabindex="0" aria-label="${esc(it.type)}: ${esc(it.name)}" data-tip="${esc(it.detail)}"><span class="type">${esc(it.type)}</span><span class="name">${esc(it.name)}</span></div>`).join('');if(!$('#cell-tip')){$('#cell-grid').insertAdjacentHTML('afterend','<div id="cell-tip">Hover or focus a cell to inspect it.</div>')}$$('#cell-grid .cell').forEach(c=>{c.onmouseenter=c.onfocus=()=>{$('#cell-tip').textContent=c.dataset.tip};c.onmouseleave=c.onblur=()=>{$('#cell-tip').textContent='Hover or focus a cell to inspect it.'}})}
function esc(x){const d=document.createElement('div');d.textContent=String(x??'');return d.innerHTML}function bindDynamic(){$$('.why').forEach(b=>b.onclick=()=>$('#trace').showModal());$$('[data-org]').forEach(b=>b.onclick=async()=>render(await api('swap',{name:b.dataset.org})));$$('[data-mut]').forEach(b=>b.onclick=async()=>render((await api('mutation',{action:b.dataset.mut})).state))}
$$('[data-view]').forEach(b=>b.onclick=()=>{$$('[data-view],.view').forEach(x=>x.classList.remove('on'));b.classList.add('on');$('#'+b.dataset.view).classList.add('on')});$('#close').onclick=()=>$('#trace').close();$('#chat').onsubmit=async e=>{e.preventDefault();const t=$('textarea');const v=t.value.trim();if(!v)return;t.disabled=true;try{let result;if(v.startsWith('/')){result=await handleCommand(v);if(result&&result.state)render(result.state)}else{result=await api('chat',{text:v});render(result.state)}t.value='';slashList=[];slashIndex=-1;showSlash()}catch(x){alert(x.message)}finally{t.disabled=false;t.focus()}};const ta=$('#chat textarea');ta.oninput=handleSlash;ta.onkeydown=e=>{if(!slashList.length)return;if(e.key==='ArrowDown'){e.preventDefault();slashIndex=(slashIndex+1)%slashList.length;showSlash()}else if(e.key==='ArrowUp'){e.preventDefault();slashIndex=(slashIndex-1+slashList.length)%slashList.length;showSlash()}else if((e.key==='Tab'||e.key==='Enter')&&slashIndex>=0){e.preventDefault();const item=slashList[slashIndex];ta.value=item.name+(item.args?' ':'')+ta.value.slice(item.name.length).trimStart();handleSlash()}};$('#slash-helper').onclick=e=>{const item=e.target.closest('.slash-item');if(!item)return;const c=COMMANDS.find(x=>x.name===item.dataset.full);if(!c)return;ta.value=c.name+(c.args?' ':'')+ta.value.slice(c.name.length).trimStart();handleSlash();ta.focus()};$('#help-close').onclick=()=>$('#help-panel').hidden=true;$('#chaos').onchange=async e=>render(await api('settings',{chaos:Number(e.target.value)}));$('#auto').onchange=async e=>render(await api('settings',{auto_apply:e.target.checked}));$('#focus').onchange=async e=>render(await api('settings',{focus:e.target.value}));$('#sleep').onclick=async()=>render((await api('lifecycle',{action:state.organism.state==='wake'?'sleep':'wake'})).state);$('#still').onclick=()=>{document.body.classList.toggle('still');$('#still').textContent=document.body.classList.contains('still')?'Resume':'Stillness'};$('#grow-name').focus();$('#grow').onsubmit=async e=>{e.preventDefault();const n=$('#grow-name').value.trim();if(!n)return;try{render(await api('organisms',{name:n}));$('#grow-name').value='';$('#grow').classList.remove('on')}catch(x){alert(x.message)}};$('#speak').onchange=e=>{speakEnabled=e.target.checked;const a=$('#speak-aside');if(a)a.checked=speakEnabled};$('#speak-aside').onchange=e=>{speakEnabled=e.target.checked;const m=$('#speak');if(m)m.checked=speakEnabled};const lb=$('#listen');if(lb){lb.disabled=!SpeechRecognition;lb.onmousedown=lb.ontouchstart=startListen;lb.onmouseup=lb.onmouseleave=lb.touchend=()=>{if(listening)stopListen()}};renderHelp();
api('state').then(render).catch(x=>document.body.innerHTML='<p>'+esc(x.message)+'</p>');'''
